// Parser et router les requêtes Vapi
const body = $input.first().json;

// Vapi envoie différents types de messages
const messageType = body.message?.type || body.type || 'unknown';

let routingInfo = {
  message_type: messageType,
  call_id: body.message?.call?.id || body.call?.id || '',
  assistant_id: body.message?.assistant?.id || body.assistant?.id || '',
  timestamp: new Date().toISOString()
};

// Si c'est un function-call
if (messageType === 'function-call' || body.message?.functionCall) {
  const functionCall = body.message?.functionCall || body.functionCall;
  routingInfo.function_name = functionCall?.name || '';
  routingInfo.function_parameters = functionCall?.parameters || {};
  routingInfo.route = 'function';
} 
// Status update
else if (messageType === 'status-update') {
  routingInfo.status = body.message?.status || '';
  routingInfo.route = 'status';
}
// End of call report
else if (messageType === 'end-of-call-report') {
  routingInfo.summary = body.message?.summary || '';
  routingInfo.transcript = body.message?.transcript || '';
  routingInfo.route = 'end-call';
}
// Assistant request (demande de config)
else if (messageType === 'assistant-request') {
  routingInfo.route = 'assistant-config';
}
else {
  routingInfo.route = 'unknown';
}

return {
  json: {
    ...routingInfo,
    raw_body: body
  }
};

// Transformer le catalogue pour Vapi
const catalog = $input.first().json;
const params = $('Parser Requête').first().json.function_parameters;

let items = [];

if (catalog.categories) {
  for (const category of catalog.categories) {
    // Filtrer par catégorie si spécifié
    if (params.category && !category.name.toLowerCase().includes(params.category.toLowerCase())) {
      continue;
    }

    if (category.products) {
      for (const productRef of category.products) {
        const product = catalog.products?.find(p => p.ref === productRef.ref);
        if (product) {
          items.push({
            id: product.ref,
            name: product.name,
            category: category.name,
            price: product.skus?.[0]?.price ? (parseInt(product.skus[0].price) / 100).toFixed(2) + '€' : 'Prix sur demande',
            description: product.description || ''
          });
        }
      }
    }
  }
}

// Formater pour lecture vocale
let menuText = 'Voici notre menu:\n\n';
const categories = [...new Set(items.map(i => i.category))];

for (const cat of categories) {
  menuText += `${cat}:\n`;
  const catItems = items.filter(i => i.category === cat);
  for (const item of catItems) {
    menuText += `- ${item.name} à ${item.price}\n`;
  }
  menuText += '\n';
}

return {
  json: {
    result: menuText,
    items: items,
    categories: categories
  }
};

// Gérer l'ajout au panier (stocké en mémoire par call_id)
const params = $input.first().json.function_parameters;
const callId = $input.first().json.call_id;

// Note: En production, utiliser Redis ou une base de données pour stocker le panier
// Ici on retourne simplement une confirmation

const response = {
  result: `J'ai bien ajouté ${params.quantity || 1} ${params.item_name} à votre commande.`,
  item_added: {
    name: params.item_name,
    quantity: params.quantity || 1,
    options: params.options || [],
    notes: params.notes || ''
  },
  call_id: callId
};

if (params.options && params.options.length > 0) {
  response.result += ` Avec les options: ${params.options.map(o => o.option_name).join(', ')}.`;
}

if (params.notes) {
  response.result += ` Note: ${params.notes}.`;
}

response.result += ' Souhaitez-vous autre chose?';

return { json: response };

// Formater les infos restaurant pour Vapi
const location = $input.first().json;
const params = $('Parser Requête').first().json.function_parameters;

const formatHours = (hours) => {
  if (!hours) return 'Horaires non disponibles';
  const days = {
    monday: 'Lundi',
    tuesday: 'Mardi',
    wednesday: 'Mercredi',
    thursday: 'Jeudi',
    friday: 'Vendredi',
    saturday: 'Samedi',
    sunday: 'Dimanche'
  };

  let text = '';
  for (const [day, label] of Object.entries(days)) {
    const dayHours = hours[day];
    if (dayHours && dayHours.length > 0) {
      text += `${label}: ${dayHours.map(h => `${h.from} à ${h.to}`).join(', ')}\n`;
    } else {
      text += `${label}: Fermé\n`;
    }
  }
  return text;
};

let result = '';
const infoType = params.info_type || 'all';

if (infoType === 'all' || infoType === 'hours') {
  result += `Nos horaires d'ouverture:\n${formatHours(location.opening_hours)}\n`;
}

if (infoType === 'all' || infoType === 'address') {
  result += `Notre adresse:\n${location.address_1 || ''}\n${location.postal_code || ''} ${location.city || ''}\n`;
}

if (infoType === 'all' || infoType === 'contact') {
  if (location.phone) result += `Téléphone: ${location.phone}\n`;
  if (location.email) result += `Email: ${location.email}\n`;
}

if (infoType === 'all' || infoType === 'services') {
  result += 'Services disponibles: ';
  const services = [];
  if (location.delivery_enabled !== false) services.push('Livraison');
  if (location.collection_enabled !== false) services.push('Retrait sur place');
  result += services.join(', ');
}

return {
  json: {
    result: result.trim(),
    location: location
  }
};

// Préparer la réponse Vapi
const data = $input.first().json;
const originalRequest = $('Parser Requête').first().json;

// Format de réponse Vapi pour function-call
const vapiResponse = {
  results: [
    {
      toolCallId: originalRequest.raw_body?.message?.functionCall?.id || 'default',
      result: data.result || JSON.stringify(data)
    }
  ]
};

return { json: vapiResponse };

// Sauvegarder le rapport de fin d'appel
const data = $input.first().json;

// Ici vous pouvez sauvegarder dans une base de données
// ou envoyer une notification

console.log('Call ended:', data.call_id);
console.log('Summary:', data.summary);

return {
  json: {
    status: 'logged',
    call_id: data.call_id
  }
};

// Soumettre la commande à HubRise
const params = $input.first().json.function_parameters;
const callId = $input.first().json.call_id;

// Préparer la commande pour HubRise
const order = {
  status: 'new',
  service_type: params.service_type || 'delivery',
  customer: {
    first_name: params.customer_first_name || '',
    last_name: params.customer_last_name || '',
    phone: params.customer_phone || '',
    email: params.customer_email || ''
  },
  custom_fields: {
    source: 'vapi_voice',
    call_id: callId
  }
};

if (params.service_type === 'delivery' && params.delivery_address) {
  order.customer.address_1 = params.delivery_address.street || '';
  order.customer.address_2 = params.delivery_address.street2 || '';
  order.customer.city = params.delivery_address.city || '';
  order.customer.postal_code = params.delivery_address.postal_code || '';
}

if (params.expected_time) {
  order.expected_time = params.expected_time;
}

if (params.notes) {
  order.customer.delivery_notes = params.notes;
}

return {
  json: {
    hubrise_order: order,
    params: params
  }
};

// Réponse pour item details
const params = $input.first().json.function_parameters;

// En production, chercher dans le catalogue HubRise
return {
  json: {
    result: `Je recherche les détails pour ${params.item_name}. Un instant...`,
    item_name: params.item_name
  }
};

// Retirer article du panier
const params = $input.first().json.function_parameters;

return {
  json: {
    result: `J'ai retiré ${params.item_name} de votre commande. Souhaitez-vous modifier autre chose?`
  }
};

// Récapitulatif de commande
// En production, récupérer depuis le stockage par call_id

return {
  json: {
    result: "Voici le récapitulatif de votre commande. Souhaitez-vous confirmer ou modifier quelque chose?"
  }
};

// Vérifier disponibilité
const params = $input.first().json.function_parameters;

return {
  json: {
    result: `Oui, ${params.item_name} est disponible. Souhaitez-vous l'ajouter à votre commande?`,
    available: true
  }
};
